         }.decodeList<TesterReport>()
         if (list.isEmpty()) return emptyList()
         val userIds = list.map { it.userId }.distinct()
         val profiles = getProfiles(userIds)
         return list.map { it.copy(testerProfile = profiles[it.userId]) }
     }
