     suspend fun deleteCampaign(campaignId: String) {
         val myProfile = getMyProfile()
         if (myProfile?.isAdmin == true) {
             try {
                 adminDeleteCampaign(campaignId)
                 return
             } catch (_: Exception) {
             }
         }
         supabase.from("campaigns").delete {
