658: CREATE OR REPLACE FUNCTION public.admin_pause_campaign(p_campaign_id uuid, p_reason text DEFAULT NULL::text)
659: RETURNS jsonb
660: LANGUAGE plpgsql
661: SECURITY DEFINER
662: SET search_path TO 'public'
663: AS $function$
664: declare
665:     v_caller_id uuid := auth.uid();
666:     v_caller_role text;
667:     v_caller_locked boolean;
668:     v_camp public.campaigns%rowtype;
669:     v_note text;
670: begin
671:     if v_caller_id is null then
672:         raise exception 'NOT_AUTHENTICATED';
673:     end if;
674: 
675:     select role, coalesce(is_locked, false)
676:     into v_caller_role, v_caller_locked
677:     from public.profiles
678:     where id = v_caller_id;
679: 
680:     if v_caller_role is null or lower(v_caller_role) != 'admin' or v_caller_locked = true then
681:         raise exception 'NOT_ADMIN';
682:     end if;
683: 
684:     select * into v_camp
685:     from public.campaigns
686:     where id = p_campaign_id
687:     for update;
688: 
689:     if v_camp.id is null then
690:         raise exception 'CAMPAIGN_NOT_FOUND';
691:     end if;
692: 
693:     if v_camp.status in ('production', 'completed') then
694:         raise exception 'CAMPAIGN_FINALIZED';
695:     end if;
696: 
697:     if v_camp.status not in ('open', 'paused') then
698:         raise exception 'CAMPAIGN_NOT_OPEN';
699:     end if;
700: 
701:     v_note := nullif(btrim(coalesce(p_reason, '')), '');
702: 
703:     if v_camp.status = 'paused'
704:        and v_camp.paused_reason = 'admin_manual'
705:        and v_camp.admin_note is not distinct from v_note then
706:         return jsonb_build_object(
707:             'success', true,
708:             'campaign_id', p_campaign_id,
709:             'previous_status', v_camp.status,
710:             'status', v_camp.status,
711:             'paused_reason', v_camp.paused_reason,
712:             'app_name', v_camp.app_name,
713:             'owner_id', v_camp.owner_id,
714:             'admin_note', v_camp.admin_note
715:         );
716:     end if;
717: 
718:     update public.campaigns
719:     set status = 'paused',
720:         paused_reason = 'admin_manual',
721:         admin_note = v_note,
722:         admin_resumed = false
723:     where id = p_campaign_id;
724: 
725:     insert into public.notifications (user_id, title, message, type, data)
726:     values (
727:         v_camp.owner_id,
728:         'Ứng dụng đã bị tạm dừng bởi Admin ⏸',
729:         format(
730:             'Ứng dụng "%s" đã bị Quản trị viên tạm dừng.%s',
731:             coalesce(nullif(v_camp.app_name, ''), 'của bạn'),
732:             case when v_note is null then '' else E'\nLý do: ' || v_note end
733:         ),
734:         'campaign',
