+const ownerUid = 'c2222222-2222-4222-8222-222222222222';
+const appUid = 'caaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
+const expiredAppUid = 'cbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';
